//go:build darwin && arm64

package sweep

import (
	"path/filepath"
	"strings"
)

// Default targets are regenerated by `pnpm install` / `npm install` or the
// next dev/build run. Matched on the exact folder name (case-sensitive).
var Default = []string{
	"node_modules", ".svelte-kit", ".turbo", ".next", ".nuxt", ".output", ".astro", ".vite",
	".parcel-cache", ".angular", ".docusaurus", ".nx", "storybook-static",
}

// Nested targets are build output inside a folder that is otherwise kept:
// only this subfolder goes. Matched on the path suffix.
var Nested = []string{
	".vercel/output", // Vercel Build Output API; .vercel/project.json must survive
}

// Build targets (--build) are opt-in: these names are sometimes committed.
var Build = []string{"dist", "build", "out"}

// Deploy targets (--deploy) are opt-in: not pure cache. .vercel/.netlify hold
// the project link (re-run `vercel link`); .wrangler/state holds local
// D1/KV/R2/Durable Objects dev data, which is lost.
var Deploy = []string{".vercel", ".netlify", ".wrangler"}

// Targets is the set of folders one run deletes.
type Targets struct {
	names  map[string]bool
	nested []string
}

func NewTargets(build, deploy bool) Targets {
	t := Targets{names: map[string]bool{}, nested: Nested}
	add := func(names []string) {
		for _, n := range names {
			t.names[n] = true
		}
	}
	add(Default)
	if build {
		add(Build)
	}
	if deploy {
		add(Deploy)
		t.nested = nil // whole .vercel goes, so .vercel/output must not be listed twice
	}
	return t
}

// Match reports whether path names a target folder.
func (t Targets) Match(path string) bool {
	if t.names[filepath.Base(path)] {
		return true
	}
	for _, n := range t.nested {
		if strings.HasSuffix(path, string(filepath.Separator)+n) {
			return true
		}
	}
	return false
}
